    public Object parsePosition(Map<String, Object> position, Map<String, Object> market)
    {
        //
        // fetchPosition
        //
        //     {
        //         "entry_price":null,
        //         "size":0,
        //         "timestamp":1605454074268079
        //     }
        //
        //
        // fetchPositions
        //
        //     {
        //         "user_id": 0,
        //         "size": 0,
        //         "entry_price": "string",
        //         "margin": "string",
        //         "liquidation_price": "string",
        //         "bankruptcy_price": "string",
        //         "adl_level": 0,
        //         "product_id": 0,
        //         "product_symbol": "string",
        //         "commission": "string",
        //         "realized_pnl": "string",
        //         "realized_funding": "string"
        //     }
        //
        String marketId = this.safeString(position, "product_symbol");
        Map<String, Object> marketResolved = (Map<String, Object>) this.safeMarket(marketId, market, (String) null, (String) null);
        String symbol = (String) ((Map<String, Object>)marketResolved).get("symbol");
        Long timestamp = this.safeIntegerProduct(position, "timestamp", 0.001);
        String sizeString = this.safeString(position, "size");
        String side = null;
        if (!java.util.Objects.equals(sizeString, null))
        {
            if (Precise.stringGt(sizeString, "0"))
            {
                side = "buy";
            } else if (Precise.stringLt(sizeString, "0"))
            {
                side = "sell";
            }
        }
        return this.safePosition(Helpers.newMap(
            "info", position,
            "id", null,
            "symbol", symbol,
            "notional", null,
            "marginMode", null,
            "liquidationPrice", this.safeNumber(position, "liquidation_price", (Object) null),
            "entryPrice", this.safeNumber(position, "entry_price", (Object) null),
            "unrealizedPnl", null,
            "percentage", null,
            "contracts", this.parseNumber(sizeString),
            "contractSize", this.safeNumber(marketResolved, "contractSize", (Object) null),
            "markPrice", null,
            "side", side,
            "hedged", null,
            "timestamp", timestamp,
            "datetime", this.iso8601(timestamp),
            "maintenanceMargin", null,
            "maintenanceMarginPercentage", null,
            "collateral", null,
            "initialMargin", null,
            "initialMarginPercentage", null,
            "leverage", null,
            "marginRatio", null,
            "stopLossPrice", null,
            "takeProfitPrice", null
        ));
    }

